116				if p.after.less(key(it)) {
117					start = i
118					break
119				}
120			}
121		}
122		end := min(start+p.limit, len(items))
123		out := items[start:end]
124		next := ""
125		if end < len(items) && len(out) > 0 {
126			next = encodeCursor(key(out[len(out)-1]))
127		}
128		return out, next
129	}
