// customerRetention is how long a deleted customer can be restored before PurgeDeletedCustomers removes it.
const customerRetention = 30 * 24 * time.Hour

// DeleteCustomer deletes a customer at the current time. See DeleteCustomerAt.
func (s *Store) DeleteCustomer(orgID, id string) error {
	return s.DeleteCustomerAt(orgID, id, time.Now())
}

// DeleteCustomerAt deletes a customer at now. A deleted customer is hidden from the organization and its email address is
// free again, but its invoices and payments stay. A customer with a subscription that is not canceled cannot be deleted.
func (s *Store) DeleteCustomerAt(orgID, id string, now time.Time) error {
	s.mu.Lock()
	defer s.mu.Unlock()
	c, ok := s.customers[id]
	if !ok || c.OrgID != orgID || c.DeletedAt != nil {
		return ErrNotFound
	}
	for _, sub := range s.subs {
		if sub.CustomerID == id && sub.Status != Canceled {
			return ErrHasActiveSubscriptions
		}
	}
	t := now.UTC()
	c.DeletedAt = &t
	s.customers[id] = c
	if s.customersByEmail[normEmail(c.Email)] == id {
		delete(s.customersByEmail, normEmail(c.Email))
	}
