	e.MustDo(http.StatusNoContent, "DELETE", "/v1/customers/"+john.ID, e.Acme.Key, nil, nil)
	e.Clock.Advance(31 * 24 * time.Hour)
	if r := e.Do("POST", "/v1/customers/"+john.ID+"/restore", e.Acme.Key, nil); r.Code != http.StatusNotFound || r.Map(t)["error"] != "not_found" {
		t.Fatalf("restore after 30 days: %s", r)
	}
	if n := e.Store.PurgeDeletedCustomers(e.Clock.Now()); n != 1 {
		t.Fatalf("purged %d customers, want 1", n)
	}
	invs.Items = nil
	e.MustDo(http.StatusOK, "GET", "/v1/invoices?customer_id="+john.ID, e.Acme.Key, nil, &invs)
	if len(invs.Items) != 1 || invs.Items[0].ID != johnInv.ID || invs.Items[0].Customer != nil {
		t.Fatalf("invoice of a purged customer = %+v", invs.Items)
	}
	if r := e.Do("GET", "/v1/invoices/"+janeInv.ID, e.Acme.Key, nil); r.Code != http.StatusOK {
		t.Fatalf("invoice of a restored customer: %s", r)
	}
}

