103	// UpdateCustomer changes a customer with f, which may refuse with an error. The ID and organization cannot change.
104	func (s *Store) UpdateCustomer(orgID, id string, f func(*Customer) error) (Customer, error) {
105		s.mu.Lock()
106		defer s.mu.Unlock()
107		old, ok := s.customers[id]
108		if !ok || old.OrgID != orgID || old.DeletedAt != nil {
109			return Customer{}, ErrNotFound
110		}
111		c := copyCustomer(old)
112		if err := f(&c); err != nil {
113			return Customer{}, err
114		}
115		c.ID, c.OrgID, c.CreatedAt, c.DeletedAt = old.ID, old.OrgID, old.CreatedAt, old.DeletedAt
116		c.Name, c.Email = strings.TrimSpace(c.Name), strings.TrimSpace(c.Email)
117		if c.Name == "" || !validEmail(c.Email) {
118			return Customer{}, invalid("a customer needs a name and a valid email address")
119		}
120		if c.DefaultPaymentMethod != "" && !strings.HasPrefix(c.DefaultPaymentMethod, "pm_") {
121			return Customer{}, invalid("a payment method looks like pm_...")
122		}
123		if newKey := normEmail(c.Email); newKey != normEmail(old.Email) {
124			if other, ok := s.customersByEmail[newKey]; ok && s.customers[other].OrgID == orgID {
125				return Customer{}, ErrEmailTaken
126			}
127			delete(s.customersByEmail, normEmail(old.Email))
128			s.customersByEmail[newKey] = c.ID
129		}
130		s.customers[id] = c
131		return copyCustomer(c), nil
132	}
